// n8n Code node (JavaScript)
// Business hours: 09:00–18:30 Eastern (America/New_York), Monday–Friday
// Random jitter: 0–20 minutes
// Output: runAt as UTC ISO string (Z) that corresponds to Eastern schedule

const MAX_JITTER_MINUTES = 20;

// ---- Timezone helpers (EST/EDT safe via America/New_York) ----
function getNYParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    weekday: 'short',
    hour12: false,
  }).formatToParts(date);

  return Object.fromEntries(parts.map(p => [p.type, p.value]));
}

// Convert NY local time → UTC Date (DST safe)
function nyLocalToUTCDate(year, month, day, hour, minute, second) {
  const guess = new Date(Date.UTC(year, month - 1, day, hour, minute, second));

  const nyAtGuess = getNYParts(guess);
  const nyAsIfUTC = Date.UTC(
    Number(nyAtGuess.year),
    Number(nyAtGuess.month) - 1,
    Number(nyAtGuess.day),
    Number(nyAtGuess.hour),
    Number(nyAtGuess.minute),
    Number(nyAtGuess.second)
  );

  const offsetMs = guess.getTime() - nyAsIfUTC;
  return new Date(guess.getTime() + offsetMs);
}

function getNYNowParts() {
  const p = getNYParts(new Date());
  return {
    year: Number(p.year),
    month: Number(p.month),
    day: Number(p.day),
    hour: Number(p.hour),
    minute: Number(p.minute),
    second: Number(p.second),
    weekday: p.weekday,
  };
}

function isNYWeekday(weekdayShort) {
  return ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'].includes(weekdayShort);
}

// Add random minutes
function addRandomMinutes(date, maxMinutes = MAX_JITTER_MINUTES) {
  const d = new Date(date.getTime());
  const jitter = Math.floor(Math.random() * (maxMinutes + 1));
  d.setMinutes(d.getMinutes() + jitter);
  return d;
}

// Clamp to 18:29 NY max
function clampToNYEndOfDayUTC(dateUtc) {
  const p = getNYParts(dateUtc);
  const hour = Number(p.hour);
  const minute = Number(p.minute);

  if (hour > 18 || (hour === 18 && minute >= 30)) {
    return nyLocalToUTCDate(
      Number(p.year),
      Number(p.month),
      Number(p.day),
      18,
      29,
      0
    );
  }
  return dateUtc;
}

function nyAtTimeUTC(year, month, day, hour, minute, second = 0) {
  return nyLocalToUTCDate(year, month, day, hour, minute, second);
}

function addDaysNY(year, month, day, daysToAdd) {
  const anchor = nyAtTimeUTC(year, month, day, 12, 0, 0);
  anchor.setUTCDate(anchor.getUTCDate() + daysToAdd);
  const p = getNYParts(anchor);
  return {
    year: Number(p.year),
    month: Number(p.month),
    day: Number(p.day),
    weekday: p.weekday
  };
}

function nextBusinessMorningUTC(nowNY) {
  let y = nowNY.year, m = nowNY.month, d = nowNY.day, wd = nowNY.weekday;

  if (!isNYWeekday(wd) || nowNY.hour >= 18 && nowNY.minute >= 30) {
    const next = addDaysNY(y, m, d, 1);
    y = next.year; m = next.month; d = next.day; wd = next.weekday;
  }

  while (!isNYWeekday(wd)) {
    const next = addDaysNY(y, m, d, 1);
    y = next.year; m = next.month; d = next.day; wd = next.weekday;
  }

  return nyAtTimeUTC(y, m, d, 9, 0, 0);
}

// ---- Main ----
const out = [];

for (const item of items) {
  const nowNY = getNYNowParts();
  const hourNY = nowNY.hour;
  const minuteNY = nowNY.minute;
  const isWeekday = isNYWeekday(nowNY.weekday);

  let shouldRunNow;
  let runAtDateUtc;

  if (
    isWeekday &&
    (
      hourNY > 9 && hourNY < 18 ||
      (hourNY === 9) ||
      (hourNY === 18 && minuteNY < 30)
    )
  ) {
    // Inside business window
    shouldRunNow = true;
    runAtDateUtc = addRandomMinutes(new Date());
    runAtDateUtc = clampToNYEndOfDayUTC(runAtDateUtc);
  } else {
    shouldRunNow = false;

    if (isWeekday && (hourNY < 9)) {
      runAtDateUtc = nyAtTimeUTC(nowNY.year, nowNY.month, nowNY.day, 9, 0, 0);
    } else {
      runAtDateUtc = nextBusinessMorningUTC(nowNY);
    }

    runAtDateUtc = addRandomMinutes(runAtDateUtc);
    runAtDateUtc = clampToNYEndOfDayUTC(runAtDateUtc);
  }

  out.push({
    json: {
      ...item.json,
      shouldRunNow,
      runAt: runAtDateUtc.toISOString(),
    },
  });
}

return out;

