const text = $('Create a record').first().json.fields['Latest Convo History'] || '';

const routeId = /\d/.test(text)
  ? '360b4199-50b5-4d4c-9950-23ca26999b2c'   // full address (has a number)
  : '7c69f0ff-746e-46fe-bbee-929bf3c9a588';  // city only

return [
  {
    json: {
      routeId,
      latestConvoHistory: text,
    },
  },
];
